const config = $('Webhook').first().json.body ?? {};

const currentYear = new Date().getUTCFullYear();

function normalizeText(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ');
}

function normalizeLinkedIn(value) {
  return normalizeText(value)
    .split('?')[0]
    .split('#')[0]
    .replace(
      /^https?:\/\/(www\.)?linkedin\.com\//,
      'linkedin.com/'
    )
    .replace(/\/+$/, '');
}

function parseRevenue(lead) {
  const rawRevenue = String(
    lead.company_annual_revenue ?? ''
  ).replace(/[$,\s]/g, '');

  if (
    rawRevenue &&
    Number.isFinite(Number(rawRevenue))
  ) {
    return Number(rawRevenue);
  }

  const cleanRevenue = String(
    lead.company_annual_revenue_clean ?? ''
  )
    .trim()
    .toUpperCase();

  const match = cleanRevenue.match(
    /^([\d.]+)\s*([KMB])?$/
  );

  if (!match) {
    return NaN;
  }

  const multiplier = {
    K: 1_000,
    M: 1_000_000,
    B: 1_000_000_000,
  }[match[2]] ?? 1;

  return Number(match[1]) * multiplier;
}

function uniqueReasons(reasons) {
  return [...new Set(reasons)];
}

const minimumRevenue = Number(
  config.minimum_revenue ?? 5_000_000
);

const maximumRevenue = Number(
  config.maximum_revenue ?? 50_000_000
);

const maximumEmployees = Number(
  config.maximum_employees ?? 50
);

const priorityStates = new Set(
  (
    config.priority_states ?? [
      'Colorado',
      'Utah',
      'California',
      'Vermont',
      'Wyoming',
    ]
  ).map(normalizeText)
);

const reviewedLeads = [];

for (const item of $input.all()) {
  const lead = item.json;

  const rejectionReasons = [];
  const reviewReasons = [];
  const positiveSignals = [];

  const title = normalizeText(
    lead.job_title
  );

  const industry = normalizeText(
    lead.industry
  );

  const companyName = String(
    lead.company_name ?? ''
  ).trim();

  const companyState = String(
    lead.company_state ??
    lead.state ??
    ''
  ).trim();

  const country = normalizeText(
    lead.company_country ??
    lead.country
  );

  const companySize = Number(
    lead.company_size
  );

  const revenue = parseRevenue(lead);

  const foundedYear = Number(
    lead.company_founded_year
  );

  const companyAge =
    Number.isFinite(foundedYear) &&
    foundedYear > 1800 &&
    foundedYear <= currentYear
      ? currentYear - foundedYear
      : null;

  /*
   * Keep strong company evidence separate from
   * provider-generated keywords.
   *
   * This prevents a logistics company from passing
   * simply because its keywords include "air charter".
   */
  const primaryCompanyText = [
    lead.company_name,
    lead.industry,
    lead.company_description,
    lead.headline,
    lead.company_domain,
  ]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();

  const keywordText = normalizeText(
    lead.keywords
  );

  /*
   * Exact decision-maker requirement.
   *
   * CMO is treated as the senior equivalent of
   * Head of Marketing.
   */
  const isCEO =
    /\bchief executive officer\b|\bceo\b/i.test(
      title
    );

  const isCOO =
    /\bchief operating officer\b|\bcoo\b/i.test(
      title
    );

  const isMarketingHead =
    /\bhead of marketing\b|\bmarketing head\b|\bchief marketing officer\b|\bcmo\b/i.test(
      title
    );

  const decisionMakerVerified =
    isCEO ||
    isCOO ||
    isMarketingHead;

  if (!decisionMakerVerified) {
    rejectionReasons.push(
      'Contact is not CEO, COO, Head of Marketing, or an equivalent marketing chief'
    );
  }

  const excludedTitle =
    /\b(jet broker|charter broker|broker|sales representative|sales rep|sales executive|account executive|pilot|dispatcher|mechanic|maintenance technician|coordinator|assistant|specialist|associate)\b/i.test(
      title
    );

  if (
    excludedTitle &&
    !decisionMakerVerified
  ) {
    rejectionReasons.push(
      'Contact has an excluded or non-decision-making role'
    );
  }

  /*
   * Mandatory geography, revenue and size rules.
   */

  if (
    ![
      'united states',
      'us',
      'usa',
    ].includes(country)
  ) {
    rejectionReasons.push(
      'Company is not based in the United States'
    );
  }

  if (!Number.isFinite(revenue)) {
    rejectionReasons.push(
      'Company revenue is missing or invalid'
    );
  } else if (
    revenue < minimumRevenue ||
    revenue > maximumRevenue
  ) {
    rejectionReasons.push(
      'Company revenue is outside the required $5M-$50M range'
    );
  }

  if (!Number.isFinite(companySize)) {
    reviewReasons.push(
      'Employee count requires verification'
    );
  } else if (
    companySize < 1 ||
    companySize > maximumEmployees
  ) {
    rejectionReasons.push(
      'Company has more than the maximum 50 employees or has an invalid employee count'
    );
  }

  /*
   * Private-aviation company verification.
   */

  const aviationIndustry =
    /\b(airlines?\/aviation|aviation and aerospace|aviation & aerospace|private aviation|air charter)\b/i.test(
      industry
    );

  const strongCoreInPrimaryText =
    /\b(private jet charter|private aircraft charter|business jet charter|executive jet charter|jet charter|aircraft charter|private charter|executive charter|charter operator|private jet operator|business jet operator|part 135|aircraft management|private jet management|fractional ownership|fractional operator|jet card|private aviation brokerage|charter brokerage|jet brokerage)\b/i.test(
      primaryCompanyText
    );

  const strongCoreInKeywords =
    /\b(private jet charter|private aircraft charter|business jet charter|jet charter|aircraft charter|charter operator|private jet operator|part 135|aircraft management|fractional ownership|fractional operator|jet card|private aviation brokerage|charter brokerage|jet brokerage)\b/i.test(
      keywordText
    );

  /*
   * Keywords are only trusted as supporting evidence
   * when the company's actual industry is aviation.
   */
  const strongPrivateAviationCore =
    strongCoreInPrimaryText ||
    (
      aviationIndustry &&
      strongCoreInKeywords
    );

  const conciergeSignal =
    /\b(concierge services|aviation concierge|luxury travel|vip travel|private clients|private families|high-net-worth|hnw|executive travel|client services|travel planning)\b/i.test(
      `${primaryCompanyText} ${keywordText}`
    );

  /*
   * FBOs may reach private-jet passengers, but they
   * are not automatically charter operators or jet
   * brokerages.
   */
  const fboOrSupportSignal =
    /\b(fixed base operator|\bfbo\b|aircraft refueling|hangar storage|de-icing|deicing|aircraft maintenance|repair station|ground handling)\b/i.test(
      primaryCompanyText
    );

  const aircraftSupplierSignal =
    /\b(aircraft interiors?|aviation interiors?|aircraft flooring|aircraft parts supplier|aviation staffing|aviation recruiting)\b/i.test(
      primaryCompanyText
    );

  /*
   * Strong false-positive categories.
   */

  const unrelatedIndustry =
    /\b(logistics|supply chain|freight|trucking|railroad|bus|motor coach|consumer goods|flooring|carpet|staffing|recruiting|oil|energy|facilities services|construction|chauffeur|ground transportation|limousine)\b/i.test(
      industry
    );

  const unrelatedCompanyDescription =
    /\b(freight forwarding|ocean freight|school bus|charter bus|motor coach|chauffeur-driven|flooring retailer|fuel distributor|staffing firm|recruitment firm)\b/i.test(
      primaryCompanyText
    );

  const standaloneTravelCompany =
    /\b(leisure, travel|travel & tourism|travel agency|tour operator|chauffeur|ground transportation)\b/i.test(
      industry
    ) &&
    !strongPrivateAviationCore;

  if (
    (
      unrelatedIndustry ||
      unrelatedCompanyDescription
    ) &&
    !strongCoreInPrimaryText
  ) {
    rejectionReasons.push(
      'Company operates in an unrelated industry rather than private aviation'
    );
  }

  if (standaloneTravelCompany) {
    rejectionReasons.push(
      'Company is a standalone travel or ground-transportation provider, not a private-jet company'
    );
  }

  if (aircraftSupplierSignal) {
    rejectionReasons.push(
      'Company is an aviation supplier or service vendor, not a private-jet operator, brokerage, or management company'
    );
  }

  if (
    fboOrSupportSignal &&
    !strongPrivateAviationCore
  ) {
    reviewReasons.push(
      'Company appears to be an FBO or aviation-support company; verify direct access to private-jet clients and partnership suitability'
    );
  }

  if (
    !strongPrivateAviationCore &&
    !fboOrSupportSignal
  ) {
    rejectionReasons.push(
      'No reliable evidence that the company is a private-jet brokerage, operator, charter company, aircraft-management company, or fractional operator'
    );
  }

  if (
    /\b(netjets|wheels up)\b/i.test(
      companyName
    )
  ) {
    rejectionReasons.push(
      'Company is specifically excluded'
    );
  }

  if (
    companyAge !== null &&
    companyAge < 3
  ) {
    reviewReasons.push(
      'Company appears very new and requires verification'
    );
  }

  if (companyAge === null) {
    reviewReasons.push(
      'Company establishment date requires verification'
    );
  }

  const isPriorityState =
    priorityStates.has(
      normalizeText(companyState)
    );

  if (strongPrivateAviationCore) {
    positiveSignals.push(
      'Strong private-aviation company evidence'
    );
  }

  if (
    Number.isFinite(revenue) &&
    revenue >= minimumRevenue &&
    revenue <= maximumRevenue
  ) {
    positiveSignals.push(
      'Revenue is within $5M-$50M'
    );
  }

  if (
    Number.isFinite(companySize) &&
    companySize >= 1 &&
    companySize <= maximumEmployees
  ) {
    positiveSignals.push(
      'Employee count is within the maximum of 50'
    );
  }

  if (conciergeSignal) {
    positiveSignals.push(
      'Concierge, luxury-travel, or private-client access signal'
    );
  }

  if (isPriorityState) {
    positiveSignals.push(
      'Located in a priority ski state'
    );
  }

  if (
    companyAge !== null &&
    companyAge >= 5
  ) {
    positiveSignals.push(
      'Established company'
    );
  }

  /*
   * Data-completeness check.
   */

  const requiredValues = [
    lead.full_name,
    lead.linkedin,
    lead.job_title,
    lead.company_name,
    lead.company_domain ??
      lead.company_website,
    country,
  ];

  const requiredFieldsComplete =
    requiredValues.every(
      value =>
        value !== undefined &&
        value !== null &&
        String(value).trim() !== ''
    ) &&
    Number.isFinite(revenue) &&
    Number.isFinite(companySize);

  if (!requiredFieldsComplete) {
    reviewReasons.push(
      'One or more required lead fields are missing'
    );
  }

  /*
   * Scoring: 0-100.
   */

  let leadScore = 0;

  // Decision maker: 25
  if (decisionMakerVerified) {
    leadScore += 25;
  }

  // Exact company type: 35
  if (strongPrivateAviationCore) {
    leadScore += 35;
  } else if (fboOrSupportSignal) {
    leadScore += 15;
  }

  // Revenue: 15
  if (
    Number.isFinite(revenue) &&
    revenue >= minimumRevenue &&
    revenue <= maximumRevenue
  ) {
    leadScore += 15;
  }

  // Employee count: 10
  if (
    Number.isFinite(companySize) &&
    companySize >= 1 &&
    companySize <= maximumEmployees
  ) {
    leadScore += 10;
  }

  // Geography: 5
  leadScore += isPriorityState
    ? 5
    : 2;

  // Established company: 5
  if (
    companyAge !== null &&
    companyAge >= 5
  ) {
    leadScore += 5;
  } else if (companyAge !== null) {
    leadScore += 2;
  }

  // Data completeness: 5
  if (requiredFieldsComplete) {
    leadScore += 5;
  }

  leadScore = Math.min(
    100,
    leadScore
  );

  const leadGrade =
    leadScore >= 85
      ? 'A'
      : leadScore >= 70
        ? 'B'
        : 'C';

  const uniqueRejectionReasons =
    uniqueReasons(rejectionReasons);

  const uniqueReviewReasons =
    uniqueReasons(reviewReasons);

  let qualificationStatus;

  if (
    uniqueRejectionReasons.length > 0
  ) {
    qualificationStatus =
      'Rejected';
  } else if (
    !strongPrivateAviationCore ||
    uniqueReviewReasons.length > 0 ||
    !requiredFieldsComplete ||
    leadGrade !== 'A'
  ) {
    qualificationStatus =
      'Needs Review';
  } else {
    qualificationStatus =
      'Qualified';
  }

  const estimatedRevenueText =
    Number.isFinite(revenue)
      ? `$${(
          revenue /
          1_000_000
        ).toFixed(1)}M`
      : 'unconfirmed revenue';

  const companyTypeText =
    strongPrivateAviationCore
      ? 'private-aviation company'
      : fboOrSupportSignal
        ? 'aviation-support or FBO company'
        : 'company outside the confirmed private-aviation ICP';

  const gptSummary =
    `${lead.full_name ?? 'This contact'} is ${lead.job_title ?? 'a contact'} at ${companyName || 'an unidentified company'}, a ${companyTypeText}. ` +
    `The company is reported at approximately ${estimatedRevenueText} in revenue with ${Number.isFinite(companySize) ? companySize : 'an unconfirmed number of'} employees. ` +
    `${
      qualificationStatus === 'Qualified'
        ? 'The lead meets the current Neuland Private Aviation Partnership criteria.'
        : qualificationStatus === 'Needs Review'
          ? 'The lead requires manual verification before it can be accepted.'
          : 'The lead does not meet the current Private Aviation Partnership criteria.'
    }`;

  const sdrNote =
    `Automated private-aviation candidate from Apify. ` +
    `Status: ${qualificationStatus}. ` +
    `${
      uniqueRejectionReasons.length
        ? `Reject because: ${uniqueRejectionReasons.join('; ')}.`
        : uniqueReviewReasons.length
          ? `Review because: ${uniqueReviewReasons.join('; ')}.`
          : 'Company and contact match the assigned ICP.'
    }`;

  reviewedLeads.push({
    json: {
      ...lead,

      revenue_numeric: revenue,
      company_age: companyAge,
      priority_state: isPriorityState,

      decision_maker_verified:
        decisionMakerVerified,

      private_aviation_core_verified:
        strongPrivateAviationCore,

      required_fields_complete:
        requiredFieldsComplete,

      lead_score: leadScore,
      lead_grade: leadGrade,

      fit_score: Math.max(
        1,
        Math.round(
          leadScore / 10
        )
      ),

      qualification_status:
        qualificationStatus,

      rejection_reasons:
        uniqueRejectionReasons.join(
          '; '
        ),

      review_reasons:
        uniqueReviewReasons.join(
          '; '
        ),

      fit_notes:
        positiveSignals.join('; '),

      company_fit_verified:
        qualificationStatus ===
        'Qualified',

      gpt_summary: gptSummary,
      sdr_note: sdrNote,

      assigned_category:
        'B2B Private Aviation',

      lead_source: 'Apify',

      added_by:
        config.added_by ??
        'OpenClaw',

      date_added:
        new Date()
          .toISOString()
          .slice(0, 10),

      next_step:
        qualificationStatus ===
        'Qualified'
          ? 'Check Monday.com and both master sheets for duplicates'
          : qualificationStatus ===
              'Needs Review'
            ? 'Manually verify company type and partnership suitability'
            : 'Do not add to the Jet tab',
    },
  });
}

/*
 * Remove duplicate people inside this Apify batch.
 *
 * This does not replace the later duplicate check
 * against Monday.com and the master sheets.
 */

const bestByPerson = new Map();

for (const item of reviewedLeads) {
  const lead = item.json;

  const linkedIn =
    normalizeLinkedIn(
      lead.linkedin
    );

  const email =
    normalizeText(
      lead.email
    );

  const nameCompany = [
    normalizeText(
      lead.full_name
    ),
    normalizeText(
      lead.company_name
    ),
  ].join('|');

  const nameTitle = [
    normalizeText(
      lead.full_name
    ),
    normalizeText(
      lead.job_title
    ),
  ].join('|');

  const personKey = linkedIn
    ? `linkedin:${linkedIn}`
    : email
      ? `email:${email}`
      : nameCompany !== '|'
        ? `name-company:${nameCompany}`
        : `name-title:${nameTitle}`;

  const existing =
    bestByPerson.get(personKey);

  if (
    !existing ||
    Number(lead.lead_score) >
      Number(existing.json.lead_score)
  ) {
    bestByPerson.set(
      personKey,
      item
    );
  }
}

const statusPriority = {
  Qualified: 1,
  'Needs Review': 2,
  Rejected: 3,
};

return [
  ...bestByPerson.values(),
].sort((a, b) => {
  const statusDifference =
    statusPriority[
      a.json.qualification_status
    ] -
    statusPriority[
      b.json.qualification_status
    ];

  if (statusDifference !== 0) {
    return statusDifference;
  }

  return (
    Number(b.json.lead_score) -
    Number(a.json.lead_score)
  );
});

/*
 * INPUT:
 * $input.all() = 944 existing rows from the Google Sheet.
 *
 * QUALIFIED LEADS:
 * Output 0 of "Route by Qualification Status".
 */

const existingRows = $input
  .all()
  .map(item => item.json);

const qualifiedLeads = $(
  'Route by Qualification Status'
)
  .all(0)
  .map(item => item.json);

function getValue(row, possibleNames) {
  for (const name of possibleNames) {
    const value = row?.[name];

    if (
      value !== undefined &&
      value !== null &&
      String(value).trim() !== ''
    ) {
      return String(value).trim();
    }
  }

  return '';
}

function normalizeText(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ');
}

function normalizeEmail(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase();
}

function normalizeLinkedIn(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase()
    .split('?')[0]
    .split('#')[0]
    .replace(/^https?:\/\/(www\.)?/, '')
    .replace(/\/+$/, '');
}

function getFullName(row) {
  const directName = getValue(row, [
    'full_name',
    'Full Name',
    'Full name',
    'Name',
    'name',
  ]);

  if (directName) {
    return normalizeText(directName);
  }

  const firstName = getValue(row, [
    'first_name',
    'First name',
    'First Name',
    'firstname',
  ]);

  const lastName = getValue(row, [
    'last_name',
    'Last Name',
    'Last name',
    'lastname',
  ]);

  return normalizeText(
    `${firstName} ${lastName}`
  );
}

function getKeys(row) {
  const linkedin = normalizeLinkedIn(
    getValue(row, [
      'linkedin',
      'Linkedin',
      'LinkedIn',
      'LinkedIn URL',
      'linkedin_url',
      'linkedinUrl',
    ])
  );

  const email = normalizeEmail(
    getValue(row, [
      'email',
      'Email',
      'Email Address',
      'work_email',
      'Work Email',
    ])
  );

  const fullName = getFullName(row);

  const company = normalizeText(
    getValue(row, [
      'company_name',
      'company name',
      'Company Name',
      'Company',
      'company',
    ])
  );

  const title = normalizeText(
    getValue(row, [
      'job_title',
      'title',
      'Title',
      'Job Title',
    ])
  );

  return {
    linkedin,
    email,

    nameCompany:
      fullName && company
        ? `${fullName}|${company}`
        : '',

    nameTitle:
      fullName && title
        ? `${fullName}|${title}`
        : '',
  };
}

/*
 * Create lookup sets from the 944 existing rows.
 */

const existingLinkedIn = new Set();
const existingEmails = new Set();
const existingNameCompany = new Set();
const existingNameTitle = new Set();

for (const row of existingRows) {
  const keys = getKeys(row);

  if (keys.linkedin) {
    existingLinkedIn.add(keys.linkedin);
  }

  if (keys.email) {
    existingEmails.add(keys.email);
  }

  if (keys.nameCompany) {
    existingNameCompany.add(
      keys.nameCompany
    );
  }

  if (keys.nameTitle) {
    existingNameTitle.add(
      keys.nameTitle
    );
  }
}

/*
 * Compare qualified leads in the required order:
 *
 * 1. LinkedIn
 * 2. Email
 * 3. Full name + company
 * 4. Full name + title
 */

const newLeads = [];

for (const lead of qualifiedLeads) {
  const keys = getKeys(lead);

  let duplicateMatchedBy = '';

  if (
    keys.linkedin &&
    existingLinkedIn.has(keys.linkedin)
  ) {
    duplicateMatchedBy = 'LinkedIn URL';
  } else if (
    keys.email &&
    existingEmails.has(keys.email)
  ) {
    duplicateMatchedBy = 'Email';
  } else if (
    keys.nameCompany &&
    existingNameCompany.has(
      keys.nameCompany
    )
  ) {
    duplicateMatchedBy =
      'Full name and company';
  } else if (
    keys.nameTitle &&
    existingNameTitle.has(
      keys.nameTitle
    )
  ) {
    duplicateMatchedBy =
      'Full name and title';
  }

  // Existing lead: skip it.
  if (duplicateMatchedBy) {
    continue;
  }

  /*
   * Add accepted lead to the sets immediately.
   * This also removes duplicates inside the
   * current qualified batch.
   */

  if (keys.linkedin) {
    existingLinkedIn.add(keys.linkedin);
  }

  if (keys.email) {
    existingEmails.add(keys.email);
  }

  if (keys.nameCompany) {
    existingNameCompany.add(
      keys.nameCompany
    );
  }

  if (keys.nameTitle) {
    existingNameTitle.add(
      keys.nameTitle
    );
  }

  newLeads.push({
    json: {
      ...lead,

      master_sheet_duplicate:
        false,

      master_sheet_duplicate_check:
        'Passed',

      next_step:
        'Check CRM sheet for duplicates',
    },
  });
}

return newLeads;

/*
 * Monday items are the direct input to this node.
 * Candidate leads are taken from:
 * "Remove Master Sheet Duplicates"
 */

const mondayItems = $input
  .all()
  .map(item => item.json);

const candidateLeads = $(
  'Remove Master Sheet Duplicates'
)
  .all()
  .map(item => item.json);

/*
 * Normalization helpers
 */

function normalizeText(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase()
    .replace(/[’']/g, '')
    .replace(/[^\p{L}\p{N}@.+:/\-\s]/gu, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function normalizeEmail(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase();
}

function normalizeLinkedIn(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase()
    .split('?')[0]
    .split('#')[0]
    .replace(/^https?:\/\/(www\.)?/, '')
    .replace(/\/+$/, '');
}

function normalizeCompany(value) {
  return normalizeText(value)
    .replace(
      /\b(incorporated|inc|llc|ltd|limited|corp|corporation)\b/g,
      ''
    )
    .replace(/\s+/g, ' ')
    .trim();
}

/*
 * Read a Monday column by its visible title.
 *
 * Monday output contains:
 * item.name
 * item.column_values[].column.title
 * item.column_values[].text
 */

function getMondayColumn(item, wantedTitles) {
  const wanted = wantedTitles.map(
    title => normalizeText(title)
  );

  const columns = Array.isArray(
    item.column_values
  )
    ? item.column_values
    : [];

  const match = columns.find(column => {
    const title = normalizeText(
      column?.column?.title
    );

    return wanted.includes(title);
  });

  if (!match) {
    return '';
  }

  if (
    match.text !== undefined &&
    match.text !== null &&
    String(match.text).trim() !== ''
  ) {
    return String(match.text).trim();
  }

  /*
   * Fallback for columns where Monday puts
   * the useful information inside "value".
   */
  if (match.value) {
    try {
      const parsed =
        typeof match.value === 'string'
          ? JSON.parse(match.value)
          : match.value;

      return String(
        parsed?.email ??
        parsed?.text ??
        parsed?.url ??
        parsed?.label ??
        ''
      ).trim();
    } catch {
      return '';
    }
  }

  return '';
}

function getMondayFullName(item) {
