function getValue(row, possibleNames) {
  for (const name of possibleNames) {
    const value = row?.[name];

    if (
      value !== undefined &&
      value !== null &&
      String(value).trim() !== ''
    ) {
      return String(value).trim();
    }
  }

  return '';
}

function normalizeText(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ');
}

function normalizeEmail(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase();
}

function normalizeLinkedIn(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase()
    .split('?')[0]
    .split('#')[0]
    .replace(/^https?:\/\/(www\.)?/, '')
    .replace(/\/+$/, '');
}

function getFullName(row) {
  const directName = getValue(row, [
    'full_name',
    'Full Name',
    'Full name',
    'Name',
    'name',
  ]);

  if (directName) {
    return normalizeText(directName);
  }

  const firstName = getValue(row, [
    'first_name',
    'First name',
    'First Name',
    'Frist Name',
    'firstname',
  ]);

  const lastName = getValue(row, [
    'last_name',
    'Last Name',
    'Last name',
    'lastname',
  ]);

  return normalizeText(
    `${firstName} ${lastName}`
  );
}

function getKeys(row) {
  const linkedin = normalizeLinkedIn(
    getValue(row, [
      'linkedin',
      'Linkedin',
      'LinkedIn',
      'LinkedIn URL',
      'linkedin_url',
      'linkedinUrl',
      'Person Linkedin',
    ])
  );

  const email = normalizeEmail(
    getValue(row, [
      'email',
      'Email',
      'Email Address',
      'work_email',
      'Work Email',
    ])
  );

  const fullName = getFullName(row);

  const company = normalizeText(
    getValue(row, [
      'company_name',
      'company name',
      'Company Name',
      'Company',
      'company',
    ])
  );

  const title = normalizeText(
    getValue(row, [
      'job_title',
      'title',
      'Title',
      'Job Title',
    ])
  );

  return {
    linkedin,
    email,

    nameCompany:
      fullName && company
        ? `${fullName}|${company}`
        : '',

    nameTitle:
      fullName && title
        ? `${fullName}|${title}`
        : '',
  };
}

/*
 * Create lookup sets from existing sheet rows.
 */

const existingLinkedIn = new Set();
const existingEmails = new Set();
const existingNameCompany = new Set();
const existingNameTitle = new Set();

for (const row of existingRows) {
  const keys = getKeys(row);

  if (keys.linkedin) {
    existingLinkedIn.add(keys.linkedin);
  }

  if (keys.email) {
    existingEmails.add(keys.email);
  }

  if (keys.nameCompany) {
    existingNameCompany.add(
