const config = $('Webhook').first().json.body ?? {};

const currentYear = new Date().getUTCFullYear();

function normalizeText(value) {
  return String(value ?? '')
    .trim()
    .toLowerCase()
    .replace(/\s+/g, ' ');
}

function normalizeLinkedIn(value) {
  return normalizeText(value)
    .split('?')[0]
    .split('#')[0]
    .replace(/^https?:\/\/(www\.)?linkedin\.com\//, 'linkedin.com/')
    .replace(/\/+$/, '');
}

function parseRevenue(lead) {
  const rawRevenue = String(lead.company_annual_revenue ?? '').replace(/[$,\s]/g, '');

  if (rawRevenue && Number.isFinite(Number(rawRevenue))) {
    return Number(rawRevenue);
  }

  const cleanRevenue = String(lead.company_annual_revenue_clean ?? '').trim().toUpperCase();
  const match = cleanRevenue.match(/^([\d.]+)\s*([KMB])?$/);

  if (!match) return NaN;

  const multiplier = { K: 1_000, M: 1_000_000, B: 1_000_000_000 }[match[2]] ?? 1;
  return Number(match[1]) * multiplier;
}

function uniqueReasons(reasons) {
  return [...new Set(reasons)];
}

const minimumRevenue = Number(config.minimum_revenue ?? 5_000_000);
const maximumRevenue = Number(config.maximum_revenue ?? 100_000_000);
const maximumEmployees = Number(config.maximum_employees ?? 50);

const priorityStates = new Set(
  (config.priority_states ?? ['Colorado', 'Utah', 'California', 'Vermont', 'Wyoming', 'New York', 'Florida']).map(normalizeText)
);

const reviewedLeads = [];

for (const item of $input.all()) {
  const lead = item.json;

  const rejectionReasons = [];
  const reviewReasons = [];
  const positiveSignals = [];

  const title = normalizeText(lead.job_title);
  const industry = normalizeText(lead.industry);
  const companyName = String(lead.company_name ?? '').trim();
  const companyState = String(lead.company_state ?? lead.state ?? '').trim();
  const country = normalizeText(lead.company_country ?? lead.country);
  const companySize = Number(lead.company_size);
  const revenue = parseRevenue(lead);
  const foundedYear = Number(lead.company_founded_year);

  const companyAge =
    Number.isFinite(foundedYear) && foundedYear > 1800 && foundedYear <= currentYear
      ? currentYear - foundedYear
      : null;

  const primaryCompanyText = [
    lead.company_name,
    lead.industry,
    lead.company_description,
    lead.headline,
    lead.company_domain,
  ].filter(Boolean).join(' ').toLowerCase();

  const keywordText = normalizeText(lead.keywords);

  // Decision-maker check for CONCIERGE
  const isDecisionMaker = /\b(founder|co-founder|ceo|chief executive officer|coo|chief operating officer|president|owner|head of concierge|head of client services|head of partnerships|head of travel|supplier relations|managing partner)\b/i.test(title);

  if (!isDecisionMaker) {
    rejectionReasons.push(
      'Contact is not Founder, CEO, COO, President, Head of Concierge, Client Services, Partnerships, Travel, or Supplier Relations'
    );
  }

  const excludedTitle = /\b(junior concierge|coordinator|assistant|specialist|associate|intern)\b/i.test(title);

  if (excludedTitle && !isDecisionMaker) {
    rejectionReasons.push('Contact has an excluded or non-decision-making role');
  }

  // Geography
  if (!['united states', 'us', 'usa'].includes(country)) {
    rejectionReasons.push('Company is not based in the United States');
  }

  // Revenue
  if (!Number.isFinite(revenue)) {
    rejectionReasons.push('Company revenue is missing or invalid');
  } else if (revenue < minimumRevenue || revenue > maximumRevenue) {
    rejectionReasons.push('Company revenue is outside the required $5M-$100M range');
  }

  // Employees
  if (!Number.isFinite(companySize)) {
    reviewReasons.push('Employee count requires verification');
  } else if (companySize < 1 || companySize > maximumEmployees) {
    rejectionReasons.push('Company has more than the maximum 50 employees or has an invalid employee count');
  }

  // CONCIERGE COMPANY VERIFICATION
  const strongConciergeCore = /\b(concierge company|concierge service|concierge business|lifestyle management|private concierge|luxury concierge|personal concierge|vip concierge|member services company|hnw concierge|high-net-worth services|private client services|luxury lifestyle management)\b/i.test(
    primaryCompanyText
  );

  const conciergeIndustry = /\b(hospitality|leisure, travel|travel & tourism|luxury goods|consumer services|events services|professional services)\b/i.test(industry);

  const affluentClientSignal = /\b(affluent|high-net-worth|hnw|luxury|vip|private clients|private families|elite|premium|exclusive|bespoke|ultra-high|wealthy|principals)\b/i.test(
    `${primaryCompanyText} ${keywordText}`
  );

  // Reject if not concierge business
  if (!strongConciergeCore) {
    rejectionReasons.push(
      'No reliable evidence that the company is a concierge, lifestyle management, or member services business'
    );
  }

  // Reject unrelated industries
  const unrelatedIndustry = /\b(pharmaceuticals|medical practice|health, wellness & fitness|construction|manufacturing|logistics|freight|trucking|railroad|oil|energy|textiles|retail|food & beverages|architecture & planning|design|real estate|public relations|advertising|events services|coffee|beverages)\b/i.test(industry);

  if (unrelatedIndustry && !strongConciergeCore) {
    rejectionReasons.push('Company operates in an unrelated industry rather than concierge/lifestyle management');
  }

  // Positive signals
  if (strongConciergeCore) positiveSignals.push('Strong concierge/lifestyle-management evidence');
  if (affluentClientSignal) positiveSignals.push('Affluent client access signal');
  if (Number.isFinite(revenue) && revenue >= minimumRevenue && revenue <= maximumRevenue) positiveSignals.push('Revenue is within $5M-$100M');
  if (Number.isFinite(companySize) && companySize >= 1 && companySize <= maximumEmployees) positiveSignals.push('Employee count is within the maximum of 50');

  const isPriorityState = priorityStates.has(normalizeText(companyState));
  if (isPriorityState) positiveSignals.push('Located in a priority state');

  if (companyAge !== null && companyAge >= 5) positiveSignals.push('Established company');

  // Data completeness
  const requiredValues = [
    lead.full_name,
    lead.linkedin,
    lead.job_title,
    lead.company_name,
    lead.company_domain ?? lead.company_website,
    country,
  ];

  const requiredFieldsComplete =
    requiredValues.every(value => value !== undefined && value !== null && String(value).trim() !== '') &&
    Number.isFinite(revenue) &&
    Number.isFinite(companySize);

  if (!requiredFieldsComplete) {
    reviewReasons.push('One or more required lead fields are missing');
  }

  // Scoring
  let leadScore = 0;
  if (isDecisionMaker) leadScore += 25;
  if (strongConciergeCore) leadScore += 30;
  if (affluentClientSignal) leadScore += 10;
  if (Number.isFinite(revenue) && revenue >= minimumRevenue && revenue <= maximumRevenue) leadScore += 15;
  if (Number.isFinite(companySize) && companySize >= 1 && companySize <= maximumEmployees) leadScore += 10;
  leadScore += isPriorityState ? 5 : 2;
  if (companyAge !== null && companyAge >= 5) leadScore += 5;
  else if (companyAge !== null) leadScore += 2;
  if (requiredFieldsComplete) leadScore += 5;

  leadScore = Math.min(100, leadScore);

  const leadGrade = leadScore >= 85 ? 'A' : leadScore >= 70 ? 'B' : 'C';

  const uniqueRejectionReasons = uniqueReasons(rejectionReasons);
  const uniqueReviewReasons = uniqueReasons(reviewReasons);

  let qualificationStatus;
  if (uniqueRejectionReasons.length > 0) {
    qualificationStatus = 'Rejected';
  } else if (!strongConciergeCore || uniqueReviewReasons.length > 0 || !requiredFieldsComplete || leadGrade !== 'A') {
    qualificationStatus = 'Needs Review';
  } else {
    qualificationStatus = 'Qualified';
  }

  const estimatedRevenueText = Number.isFinite(revenue) ? `$${(revenue / 1_000_000).toFixed(1)}M` : 'unconfirmed revenue';

  const companyTypeText = strongConciergeCore
    ? 'concierge/lifestyle-management company'
    : 'company outside the confirmed concierge ICP';

  const gptSummary =
    `${lead.full_name ?? 'This contact'} is ${lead.job_title ?? 'a contact'} at ${companyName || 'an unidentified company'}, a ${companyTypeText}. ` +
    `The company is reported at approximately ${estimatedRevenueText} in revenue with ${Number.isFinite(companySize) ? companySize : 'an unconfirmed number of'} employees. ` +
    `${
      qualificationStatus === 'Qualified'
        ? 'The lead meets the current Neuland Concierge Partnership criteria.'
        : qualificationStatus === 'Needs Review'
          ? 'The lead requires manual verification before it can be accepted.'
          : 'The lead does not meet the current Concierge Partnership criteria.'
    }`;

  const sdrNote =
    `Automated concierge candidate from Apify. ` +
    `Status: ${qualificationStatus}. ` +
    `${
      uniqueRejectionReasons.length
        ? `Reject because: ${uniqueRejectionReasons.join('; ')}.`
        : uniqueReviewReasons.length
          ? `Review because: ${uniqueReviewReasons.join('; ')}.`
          : 'Company and contact match the assigned ICP.'
    }`;

  reviewedLeads.push({
    json: {
      ...lead,
      revenue_numeric: revenue,
      company_age: companyAge,
      priority_state: isPriorityState,
      decision_maker_verified: isDecisionMaker,
      concierge_core_verified: strongConciergeCore,
      required_fields_complete: requiredFieldsComplete,
      lead_score: leadScore,
      lead_grade: leadGrade,
      fit_score: Math.max(1, Math.round(leadScore / 10)),
      qualification_status: qualificationStatus,
      rejection_reasons: uniqueRejectionReasons.join('; '),
      review_reasons: uniqueReviewReasons.join('; '),
      fit_notes: positiveSignals.join('; '),
      company_fit_verified: qualificationStatus === 'Qualified',
      gpt_summary: gptSummary,
      sdr_note: sdrNote,
      assigned_category: 'B2B Concierge',
      lead_source: 'Apify',
      added_by: config.added_by ?? 'OpenClaw',
      date_added: new Date().toISOString().slice(0, 10),
      next_step:
        qualificationStatus === 'Qualified'
          ? 'Check Monday.com and both master sheets for duplicates'
          : qualificationStatus === 'Needs Review'
            ? 'Manually verify company type and partnership suitability'
            : 'Do not add to the sheet',
    },
  });
}

