  let duplicateMatchedBy = '';

  if (
    keys.linkedin &&
    existingLinkedIn.has(keys.linkedin)
  ) {
    duplicateMatchedBy = 'LinkedIn URL';
  } else if (
    keys.email &&
    existingEmails.has(keys.email)
  ) {
    duplicateMatchedBy = 'Email';
  } else if (
    keys.nameCompany &&
    existingNameCompany.has(
      keys.nameCompany
    )
  ) {
    duplicateMatchedBy =
      'Full name and company';
  } else if (
    keys.nameTitle &&
    existingNameTitle.has(
      keys.nameTitle
    )
  ) {
    duplicateMatchedBy =
      'Full name and title';
  }

  // Existing lead: skip it.
  if (duplicateMatchedBy) {
    continue;
  }

  /*
