const config = $('Webhook').first().json.body ?? {};

const currentYear = new Date().getUTCFullYear();

function normalizeText(value) {
  return String(value ?? '').trim().toLowerCase().replace(/\s+/g, ' ');
}

function normalizeLinkedIn(value) {
  return normalizeText(value)
    .split('?')[0]
    .split('#')[0]
    .replace(/^https?:\/\/(www\.)?linkedin\.com\//, 'linkedin.com/')
    .replace(/\/+$/, '');
}

function parseRevenue(lead) {
  const rawRevenue = String(lead.company_annual_revenue ?? '').replace(/[$,\s]/g, '');
  if (rawRevenue && Number.isFinite(Number(rawRevenue))) return Number(rawRevenue);

  const cleanRevenue = String(lead.company_annual_revenue_clean ?? '').trim().toUpperCase();
  const match = cleanRevenue.match(/^([\d.]+)\s*([KMB])?$/);
  if (!match) return NaN;

  const multiplier = { K: 1_000, M: 1_000_000, B: 1_000_000_000 }[match[2]] ?? 1;
  return Number(match[1]) * multiplier;
}

function uniqueReasons(reasons) {
  return [...new Set(reasons)];
}

const minimumRevenue = Number(config.minimum_revenue ?? 5_000_000);
const maximumRevenue = Number(config.maximum_revenue ?? 500_000_000);
const maximumEmployees = Number(config.maximum_employees ?? 50);

const priorityStates = new Set(
  (config.priority_states ?? ['Colorado', 'Utah', 'California', 'Vermont', 'Wyoming', 'New York', 'Florida', 'Texas']).map(normalizeText)
);

const reviewedLeads = [];

for (const item of $input.all()) {
  const lead = item.json;
  const rejectionReasons = [];
  const reviewReasons = [];
  const positiveSignals = [];

  const title = normalizeText(lead.job_title);
  const industry = normalizeText(lead.industry);
  const companyName = String(lead.company_name ?? '').trim();
  const companyState = String(lead.company_state ?? lead.state ?? '').trim();
  const country = normalizeText(lead.company_country ?? lead.country);
  const companySize = Number(lead.company_size);
  const revenue = parseRevenue(lead);
  const foundedYear = Number(lead.company_founded_year);

  const companyAge = Number.isFinite(foundedYear) && foundedYear > 1800 && foundedYear <= currentYear
    ? currentYear - foundedYear : null;

  const primaryCompanyText = [
    lead.company_name,
    lead.industry,
    lead.company_description,
    lead.headline,
    lead.company_domain,
  ].filter(Boolean).join(' ').toLowerCase();

  const keywordText = normalizeText(lead.keywords);

  // Decision-maker check for FAMILY OFFICES
  const isDecisionMaker = /\b(principal|partner|managing partner|coo|chief of staff|head of member services|head of travel|head of lifestyle|head of partnerships|executive assistant|founder|ceo|president|owner)\b/i.test(title);

  if (!isDecisionMaker) {
    rejectionReasons.push(
      'Contact is not Principal, Partner, COO, Chief of Staff, Head of Member Services, Travel, Lifestyle, Partnerships, or executive assistant managing principal travel'
    );
  }

  const excludedTitle = /\b(junior|coordinator|specialist|associate|intern)\b/i.test(title);
  if (excludedTitle && !isDecisionMaker) {
    rejectionReasons.push('Contact has an excluded or non-decision-making role');
  }

  // Geography
  if (!['united states', 'us', 'usa'].includes(country)) {
    rejectionReasons.push('Company is not based in the United States');
  }

  // Revenue
  if (!Number.isFinite(revenue)) {
    rejectionReasons.push('Company revenue is missing or invalid');
  } else if (revenue < minimumRevenue || revenue > maximumRevenue) {
    rejectionReasons.push('Company revenue is outside the required $5M-$500M range');
  }

  // Employees
  if (!Number.isFinite(companySize)) {
    reviewReasons.push('Employee count requires verification');
  } else if (companySize < 1 || companySize > maximumEmployees) {
    rejectionReasons.push('Company has more than the maximum 50 employees or has an invalid employee count');
  }

  // FAMILY OFFICE / HNW NETWORK VERIFICATION
  const strongFamilyOfficeCore = /\b(family office|multi-family office|single family office|hnw network|high-net-worth network|founder network|founders network|private members club|hnw membership|private club|wealth network|investor network|hnw community|family wealth|principal support|private wealth office)\b/i.test(
    `${primaryCompanyText} ${keywordText}`
  );

  const affluentClientSignal = /\b(affluent|high-net-worth|hnw|ultra-high|luxury|vip|private clients|principals|wealthy|family wealth|billionaire|millionaire|private wealth)\b/i.test(
    `${primaryCompanyText} ${keywordText}`
  );

  if (!strongFamilyOfficeCore) {
    rejectionReasons.push(
      'No reliable evidence that the company is a family office, HNW network, private club, or founder network'
    );
  }

  // Reject unrelated industries
  const unrelatedIndustry = /\b(pharmaceuticals|medical practice|health, wellness|construction|manufacturing|logistics|freight|trucking|railroad|oil|energy|textiles|retail|food & beverages|architecture|design|real estate brokerage|public relations|advertising|events services|coffee|beverages|physical therapy)\b/i.test(industry);

  if (unrelatedIndustry) {
    rejectionReasons.push('Company operates in an unrelated industry rather than family office / HNW networks');
  }

  // Positive signals
  if (strongFamilyOfficeCore) positiveSignals.push('Strong family-office/HNW-network evidence');
  if (affluentClientSignal) positiveSignals.push('Affluent client/principal access signal');
  if (Number.isFinite(revenue) && revenue >= minimumRevenue && revenue <= maximumRevenue) positiveSignals.push('Revenue is within $5M-$500M');
  if (Number.isFinite(companySize) && companySize >= 1 && companySize <= maximumEmployees) positiveSignals.push('Employee count is within the maximum of 50');

  const isPriorityState = priorityStates.has(normalizeText(companyState));
  if (isPriorityState) positiveSignals.push('Located in a priority state');

  if (companyAge !== null && companyAge >= 5) positiveSignals.push('Established company');

  // Data completeness
  const requiredValues = [
    lead.full_name,
    lead.linkedin,
    lead.job_title,
    lead.company_name,
    lead.company_domain ?? lead.company_website,
    country,
  ];

  const requiredFieldsComplete = requiredValues.every(v => v !== undefined && v !== null && String(v).trim() !== '') &&
    Number.isFinite(revenue) && Number.isFinite(companySize);

  if (!requiredFieldsComplete) reviewReasons.push('One or more required lead fields are missing');

  // Scoring
  let leadScore = 0;
  if (isDecisionMaker) leadScore += 25;
  if (strongFamilyOfficeCore) leadScore += 30;
  if (affluentClientSignal) leadScore += 10;
  if (Number.isFinite(revenue) && revenue >= minimumRevenue && revenue <= maximumRevenue) leadScore += 15;
  if (Number.isFinite(companySize) && companySize >= 1 && companySize <= maximumEmployees) leadScore += 10;
  leadScore += isPriorityState ? 5 : 2;
  if (companyAge !== null && companyAge >= 5) leadScore += 5;
  else if (companyAge !== null) leadScore += 2;
  if (requiredFieldsComplete) leadScore += 5;

  leadScore = Math.min(100, leadScore);
  const leadGrade = leadScore >= 85 ? 'A' : leadScore >= 70 ? 'B' : 'C';

  const uniqueRejectionReasons = uniqueReasons(rejectionReasons);
  const uniqueReviewReasons = uniqueReasons(reviewReasons);

  let qualificationStatus;
  if (uniqueRejectionReasons.length > 0) {
    qualificationStatus = 'Rejected';
  } else if (!strongFamilyOfficeCore || uniqueReviewReasons.length > 0 || !requiredFieldsComplete || leadGrade !== 'A') {
    qualificationStatus = 'Needs Review';
  } else {
    qualificationStatus = 'Qualified';
  }

  const estimatedRevenueText = Number.isFinite(revenue) ? `$${(revenue / 1_000_000).toFixed(1)}M` : 'unconfirmed revenue';

  const companyTypeText = strongFamilyOfficeCore
    ? 'family office / HNW network'
    : 'company outside the confirmed family office ICP';

  const gptSummary =
    `${lead.full_name ?? 'This contact'} is ${lead.job_title ?? 'a contact'} at ${companyName || 'an unidentified company'}, a ${companyTypeText}. ` +
    `The company is reported at approximately ${estimatedRevenueText} in revenue with ${Number.isFinite(companySize) ? companySize : 'an unconfirmed number of'} employees. ` +
    `${
      qualificationStatus === 'Qualified'
        ? 'The lead meets the current Neuland Family Office Partnership criteria.'
        : qualificationStatus === 'Needs Review'
          ? 'The lead requires manual verification before it can be accepted.'
          : 'The lead does not meet the current Family Office Partnership criteria.'
    }`;

  const sdrNote =
    `Automated family-office candidate from Apify. ` +
    `Status: ${qualificationStatus}. ` +
    `${
      uniqueRejectionReasons.length
        ? `Reject because: ${uniqueRejectionReasons.join('; ')}.`
        : uniqueReviewReasons.length
          ? `Review because: ${uniqueReviewReasons.join('; ')}.`
          : 'Company and contact match the assigned ICP.'
    }`;

  reviewedLeads.push({
    json: {
      ...lead,
      revenue_numeric: revenue,
      company_age: companyAge,
      priority_state: isPriorityState,
      decision_maker_verified: isDecisionMaker,
      family_office_core_verified: strongFamilyOfficeCore,
      required_fields_complete: requiredFieldsComplete,
      lead_score: leadScore,
      lead_grade: leadGrade,
      fit_score: Math.max(1, Math.round(leadScore / 10)),
      qualification_status: qualificationStatus,
      rejection_reasons: uniqueRejectionReasons.join('; '),
      review_reasons: uniqueReviewReasons.join('; '),
      fit_notes: positiveSignals.join('; '),
      company_fit_verified: qualificationStatus === 'Qualified',
      gpt_summary: gptSummary,
      sdr_note: sdrNote,
      assigned_category: 'B2B Family Office',
      lead_source: 'Apify',
      added_by: config.added_by ?? 'OpenClaw',
      date_added: new Date().toISOString().slice(0, 10),
      next_step:
        qualificationStatus === 'Qualified'
          ? 'Check Monday.com and both master sheets for duplicates'
          : qualificationStatus === 'Needs Review'
            ? 'Manually verify company type and partnership suitability'
            : 'Do not add to the sheet',
    },
  });
}

// Deduplicate within batch
const bestByPerson = new Map();

for (const item of reviewedLeads) {
  const lead = item.json;
  const linkedIn = normalizeLinkedIn(lead.linkedin);
  const email = normalizeText(lead.email);
  const nameCompany = [normalizeText(lead.full_name), normalizeText(lead.company_name)].join('|');
  const nameTitle = [normalizeText(lead.full_name), normalizeText(lead.job_title)].join('|');

  const personKey = linkedIn
    ? `linkedin:${linkedIn}`
    : email
      ? `email:${email}`
      : nameCompany !== '|'
        ? `name-company:${nameCompany}`
        : `name-title:${nameTitle}`;

  const existing = bestByPerson.get(personKey);
  if (!existing || Number(lead.lead_score) > Number(existing.json.lead_score)) {
    bestByPerson.set(personKey, item);
  }
}

const statusPriority = { Qualified: 1, 'Needs Review': 2, Rejected: 3 };

return [...bestByPerson.values()].sort((a, b) => {
  const statusDifference = statusPriority[a.json.qualification_status] - statusPriority[b.json.qualification_status];
  if (statusDifference !== 0) return statusDifference;
  return Number(b.json.lead_score) - Number(a.json.lead_score);
});

