    lead['Email Address']
  );

  const company = normalizeCompany(
    lead.company_name ??
    lead['company name'] ??
    lead['Company Name'] ??
    lead.Company
  );

  const title = normalizeText(
    lead.job_title ??
    lead.title ??
    lead.Title ??
    lead['Job Title']
  );

  return {
